# Prints the list index of the only programmer nobody beats, or -1 if there isn't exactly one
N, M = map(int, input().split())

flag = [1] * N
beaten_by = [0] * N

for i in range(M):
    a, b = map(int, input().split())
    beaten_by[b-1] += 1

for i in range(N):
    if beaten_by[i] == 0:
        flag[i] = 0

if sum(flag) == 1:
    print(flag.index(1))
else:
    print(-1)

